"""Plain-English glossary. Each entry: key -> (term, explanation). Used by tooltips, "?" icons and the Glossary dialog."""

GLOSSARY = {
    # ---- basics
    "model": ("Model", "The program that learns. It starts out knowing nothing (random numbers) and slowly adjusts those numbers while reading your examples, like a student who starts with a blank notebook."),
    "parameters": ("Parameters", "The adjustable numbers inside the model - its 'memory'. More parameters can learn more, but need more time and memory. A small model here has about 100 thousand; big chatbots have billions."),
    "training": ("Training", "Showing the model your examples over and over and nudging its numbers each time so its guesses get a little better. Like practising scales on a piano."),
    "dataset": ("Dataset", "A collection of examples (a prompt and the answer you want). It is the textbook your model studies."),
    "example": ("Example", "One lesson for the model: a question (prompt) and the answer you want it to give, or a piece of plain text."),
    "prompt": ("Prompt", "What you type to the model: a question or instruction."),
    "token": ("Token", "A small chunk of text the model reads at a time - here a single character or byte. 'cat' is 3 tokens."),
    "synthetic": ("Synthetic data", "Examples made by a program or by a helper model instead of collected from people. Handy for filling gaps, but worth reviewing."),
    "review_good": ("Review vs Good", "'Review' means nobody has looked at this example yet. 'Good' means you checked it and approve. You can train on everything, or on Good examples only."),
    "import_format": ("Importing files", "Each example needs a question and an answer. JSONL: one line per example like {\"user\": \"...\", \"assistant\": \"...\"}. CSV or TSV: columns named user and assistant (or prompt and response). TXT: plain text, one document per file or blank-line separated. Exact duplicates are skipped."),
    "duplicates": ("Duplicates", "Examples that are exactly the same as another one. They waste training time, so they are skipped automatically."),
    "provenance": ("Provenance", "The record of where an example came from (which download, which generator, which helper model), so you can always trace it."),
    "mixture": ("Mixture", "Training on several datasets at once, like a diet with several food groups. The weights say how much of each to include."),
    "record_budget": ("Record budget", "The most examples used for one training run. A smaller budget means faster preparation; 10,000 is plenty for a first try."),
    "balance": ("Balance by", "How to share the budget between datasets. 'tokens' gives each dataset an equal amount of text so a dataset with very long answers does not take over. 'records' splits by number of examples."),
    "reviewed_only": ("Reviewed examples only", "Train only on examples marked Good. Safer, but you need to have reviewed some first."),
    "weight": ("Weight", "How much a dataset or rule matters compared with the others. 2 means twice as important as 1."),
    "teacher": ("Teacher model", "A bigger helper model running on your computer (through Ollama) that writes examples or grades answers for your small model, like a tutor."),
    "ollama": ("Ollama", "A free program that runs large language models on your own computer. The studio uses it as a 'teacher' if you have it installed."),
    "difficulty": ("Difficulty", "How hard the generated problems are. 'curriculum' starts easy and ramps up, like a textbook."),
    "seed": ("Random seed", "A number that fixes the 'random' choices. Same seed and same data give the same result, so experiments can be repeated."),
    "quality_gates": ("Quality gates", "Automatic checks that throw away generated examples that are too short, too long, repetitive or contradictory. They are rules of thumb, not fact-checks."),
    # ---- blueprint
    "preset": ("Model size", "A ready-made size for the model. Bigger can learn more but trains slower. When unsure, pick Small."),
    "width": ("Embedding width", "How many numbers describe each token inside the model. Think of the size of the 'notes' it keeps about every character. Wider = more capacity, more time."),
    "layers": ("Layers (transformer blocks)", "How many processing steps the text passes through. More layers let the model combine ideas in more steps, like a longer assembly line."),
    "heads": ("Attention heads", "How many different things the model can look at at once while reading, e.g. one head tracks the previous word, another tracks the topic. Must divide the width evenly."),
    "context": ("Context length", "How much text (in tokens) the model can see at once - its short-term memory. 256 is about one short paragraph."),
    "expansion": ("Feed-forward size (MLP expansion)", "Inside each layer there is a 'thinking' sub-network. This multiplier sets how much wider it gets in the middle. 4 is the usual choice; higher = more capacity and slower."),
    "dropout": ("Dropout", "Randomly switches off a share of the model's connections while learning so it cannot just memorize. 0.1 means 10%. Use 0 for tiny datasets you want memorized exactly."),
    "tokenizer": ("Tokenizer", "How text is chopped into tokens. 'byte' handles any language and emoji with a small fixed alphabet. 'character' learns the exact characters in your data."),
    "steps": ("Training steps", "How many times the model adjusts itself. Each step reads a small batch of examples. More steps = more learning, but also longer. Try 300 to start."),
    "batch_size": ("Batch size", "How many text snippets the model reads before each adjustment. Bigger is steadier but needs more memory."),
    "accumulation": ("Gradient accumulation", "Reads several small batches before adjusting once, which acts like a bigger batch without needing more memory. 1 means off."),
    "learning_rate": ("Learning rate", "How big each adjustment is. Too high and the model overshoots and gets worse; too low and it learns painfully slowly. Like the size of the steps when walking downhill in fog."),
    "weight_decay": ("Weight decay", "A gentle pull that keeps the model's numbers small, which discourages memorizing. 0.01 is a safe default."),
    "warmup": ("Warmup steps", "At the very start the learning rate is raised slowly from zero, like warming up before a run. It prevents wild early mistakes."),
    "eval_every": ("Evaluate every N steps", "How often to pause and test the model on examples it has not trained on, giving the blue 'validation' line on the chart."),
    "validation": ("Validation fraction", "The share of your data hidden away and used only for testing, never for learning. 0.1 = 10%. It tells you whether the model really learned or just memorized."),
    "objective": ("Train on (objective)", "'assistant' teaches the model only to write the answers. 'all' also teaches it to predict the questions. 'assistant' is better for chat."),
    "windowing": ("Windows", "How long texts are cut into model-sized pieces. 'anchored' keeps each answer together with as much of its question as fits. 'sequential' cuts plain chunks one after another."),
    "device": ("Device (CPU or GPU)", "Where the maths runs. A GPU (NVIDIA 'CUDA') is much faster for bigger models. 'auto' uses the GPU if one works, otherwise the CPU."),
    "cuda": ("CUDA / GPU", "NVIDIA's technology for running maths on a graphics card. PyTorch uses it when a supported NVIDIA card and driver are present; Apple GPUs are used through Metal (MPS)."),
    "estimate_time": ("Training time estimate", "A rough guess from your model size, steps and device. It improves after your first run because the studio learns how fast your computer is."),
    "model_name": ("Model name", "Just a label so you can recognise this model in your list of runs."),
    # ---- training
    "loss": ("Loss (error)", "A score for how wrong the model's guesses are. Lower is better. A brand-new model scores around 5.5; a model that has learned simple patterns gets below 2."),
    "train_loss": ("Training loss", "How wrong the model is on the examples it is currently studying. It should fall steadily."),
    "val_loss": ("Validation loss", "How wrong the model is on examples it has NOT studied. This is the honest score. If it stops falling or rises while training loss keeps falling, the model is memorizing."),
    "tokens_sec": ("Tokens per second", "Speed of training: how much text the model reads each second. Higher = faster. Useful for judging whether a GPU is helping."),
    "cross_entropy": ("Cross-entropy", "The exact formula behind 'loss': it measures how surprised the model is by the right next character. Less surprise = better."),
    "checkpoint": ("Checkpoint", "A saved copy of the model's numbers at some moment (a .npz file). It is like a save-game: you can chat with it, keep training from it, or share it."),
    "overfitting": ("Overfitting (memorizing)", "When the model learns your examples by heart instead of learning the pattern. Sign: training loss keeps falling but validation loss rises. Fix: stop earlier, add more data, or raise dropout."),
    "step": ("Step", "One adjustment of the model. The step counter shows progress through the run."),
    "run": ("Run", "One training session and everything it saved: checkpoints, the loss history and a copy of the data used."),
    "resume": ("Resume", "Continue training a saved checkpoint for more steps instead of starting over from random numbers."),
    "curriculum": ("Sequential training (curriculum)", "Teaching in stages like school: easy language first, then instructions, code, reasoning. After each stage the model is re-tested on earlier ones to see what it forgot."),
    "replay": ("Replay earlier data", "Mixing a little of the old lessons into each new stage so the model does not forget them."),
    "forgetting": ("Forgetting", "When learning something new makes the model worse at something it learned before."),
    # ---- chat
    "temperature": ("Temperature", "How adventurous the model is when choosing words. 0 always picks its top guess (safe, repetitive). Around 0.8 is balanced. Above 1.2 gets creative and often nonsensical."),
    "top_k": ("Top-k", "Only the k most likely next characters are considered. 40 trims the silly options; 0 allows everything."),
    "max_tokens": ("New tokens", "The longest reply the model may write, counted in tokens. About 4 tokens is one word for characters, so 160 is a short paragraph."),
    "npz": (".npz file", "The file format of a saved model checkpoint. Your trained models are stored as best.npz (lowest error) and last.npz (most recent)."),
    "system_prompt": ("System prompt", "Standing instructions placed before the conversation, e.g. 'Answer briefly'. Optional. Small models follow it only if they were trained with it."),
    "correction": ("This reply is wrong", "Sends the conversation to Improve with feedback, where you pick a better reply or write the right one. An answer you write is also saved as a new example in your working dataset."),
    "inference": ("Inference device", "Where the model runs when you chat with it. 'auto' picks the GPU if available."),
    # ---- network
    "block": ("Block", "One repeatable layer of the network: it reads the text so far, combines information, and passes it on. A model stacks several blocks."),
    "attention": ("Attention", "The part of a block that lets each token look back at earlier ones and decide which matter. Like highlighting the relevant words in a sentence before answering. The most capable token mixer, but its cost grows with the square of the text length."),
    "mlp": ("MLP (feed-forward network)", "The part of a block that 'thinks' about each position by itself after attention has gathered the information."),
    "residual": ("Residual stream", "The main highway of numbers running through the model. Each part adds its contribution on top instead of replacing it, which keeps learning stable."),
    "revision": ("Revision", "A numbered snapshot of your network design. Every valid edit is saved, so you can always go back."),
    "activation": ("Activation function", "A small non-linear twist applied inside the MLP so the network can learn curved, not just straight-line, relationships. GELU is smooth; ReLU is simpler."),
    "hidden_layers": ("Hidden layers", "How many layers the MLP sub-network has inside one block."),
    "layernorm": ("LayerNorm", "A step that keeps numbers at a steady scale so training does not blow up: it re-centres each token's numbers and rescales them. The GPT-2 choice and a safe default."),
    "embedding": ("Token embedding", "A table that turns each token into a list of numbers (a vector), which is the form the model works with."),
    "net_training": ("Network training settings", "These belong to the selected architecture and are used by Train this architecture. They are separate from the Training setup page, which only supplies the data."),
    "arch_weights": ("Initial weights", "Where training starts: random numbers for a brand-new model, or the saved numbers of an earlier run to keep improving it."),
    # ---- model parts (the Builder's tower); MODULE_TERMS below maps every registry module to one of these
    "norm": ("Normalization (even out)", "Rescales each token's numbers to a steady size before the next step works on them. Without it, numbers can grow or shrink layer by layer until training breaks. Almost every modern model keeps one."),
    "rmsnorm": ("RMSNorm", "A simpler LayerNorm: it only rescales by the typical size of the numbers and skips re-centring them. Slightly faster, works as well in practice, and is what LLaMA-style models use."),
    "no_norm": ("No normalization", "Leaves the numbers as they are. Not a good choice for real training; pick it to see why normalization matters, as deeper models often become unstable without it."),
    "token_mixer": ("Token mixer (look back)", "The part of a block that lets each token use the tokens before it. Attention is the usual choice; the others trade some of its power for speed or memory on long texts."),
    "gqa": ("GQA (grouped-query attention)", "Attention where several heads share one set of keys and values. Nearly as good as full attention but needs less memory when generating, which is why large models use it."),
    "linear_attention": ("Linear attention", "An approximation of attention whose cost grows in a straight line with the text length instead of with its square. Cheaper on long texts, usually a bit less accurate."),
    "ssm": ("SSM (state space model)", "Carries a running summary (a state) along the text and updates it token by token, like Mamba. Fast on long texts; good at smooth, flowing patterns, weaker at copying exact earlier words."),
    "gru": ("GRU (gated recurrent unit)", "A classic recurrent network: a memory passed from token to token, with gates deciding what to keep. Simple and small, but it trains step by step, so it is slow on long texts."),
    "lstm": ("LSTM (long short-term memory)", "A recurrent network with a separate long-term memory cell and three gates. It holds on to information longer than a GRU but is larger and also trains step by step."),
    "conv": ("Causal convolution", "Looks at a small fixed window of recent tokens. Very fast and good at local patterns such as spelling, but it cannot reach far back on its own."),
    "no_mixer": ("No token mixer", "This block does not look at other tokens at all; each token is processed alone. Useful to see how much looking back matters."),
    "mlp_gelu": ("MLP with GELU", "The usual thinking room: widen each token's numbers (4 times by default), bend them with GELU, a smooth on/off curve, then narrow them back. The standard choice in GPT-2-style models."),
    "swiglu": ("SwiGLU", "A gated MLP: one half of the widened numbers decides how much of the other half passes through. Used in LLaMA and PaLM; often learns a little better for the same size."),
    "moe": ("MoE (mixture of experts)", "Several MLPs (experts) with a router that sends each token to only the best few. Many more parameters for about the same work per token; harder to train well."),
    "no_channel": ("No thinking room", "Leaves out the MLP. Common in SSM blocks, which do their own mixing; weak for attention models, which rely on the MLP to store what they learn."),
    "position": ("Position encoding", "Tells the model where each token sits in the text. Attention on its own sees a set of tokens, not their order, so it needs this; recurrent mixers already know the order."),
    "learned_position": ("Learned position", "A trainable vector for every position, added to the token's numbers, as in GPT-2. Simple and good, but it cannot handle texts longer than it was trained on."),
    "sinusoidal": ("Sinusoidal position", "Fixed sine and cosine waves of different speeds mark each position, as in the original Transformer. Nothing to learn, and every position gets a distinct pattern."),
    "rope": ("RoPE (rotary position embedding)", "Rotates attention's queries and keys by an angle that depends on position, so attention sees how far apart two tokens are. Used by most modern models; needs an attention mixer."),
    "alibi": ("ALiBi (attention with linear biases)", "Makes attention pay a little less attention to tokens the further back they are. No learned weights, copes well with longer texts; needs an attention mixer."),
    "nope": ("No position (NoPE)", "Gives no position signal. Recurrent and convolution mixers know the order anyway; attention can still guess some order from only seeing earlier tokens."),
    "factorized_embedding": ("Factorized embedding", "Builds the token table from two smaller tables, as in ALBERT. Saves many parameters when the word list is large and the model is small."),
    "output_head": ("Output head (word scores)", "Turns the last block's numbers into a score for every entry in the word list; the highest scores are the likeliest next pieces."),
    "tied_head": ("Tied head", "Reuses the token table (embedding) backwards to score words, so it adds no parameters. The usual choice for small models."),
    "untied_head": ("Untied head", "A separate table for scoring words. More parameters, and the reading and writing tables can specialise; bigger models sometimes prefer it."),
    "bytes": ("Letters (bytes)", "Each byte of text is one piece: 256 entries, any language or emoji works, nothing is ever unknown. Texts become long, so each step covers less text."),
    "bpe": ("BPE (byte-pair encoding)", "Builds a word list by repeatedly merging the most common neighbouring pieces, so frequent words become one piece and rare ones split into parts. Shorter texts than letters, still nothing unknown."),
    "gpt2_bpe": ("GPT-2's word list", "The 50,257-piece BPE list GPT-2 was trained with. Short texts, but a huge word table that dominates a small model's size."),
    "whole_words": ("Whole words", "One entry per frequent word or punctuation mark in your data. Very short texts, but any word that is not in the list is lost."),
    # ---- align
    "rlhf": ("Feedback training (RLHF)", "Improving a model by telling it which of its answers are better. It polishes a model that already writes sensible text; it cannot teach language from scratch."),
    "dpo": ("DPO", "Direct Preference Optimization: a training method that makes the preferred reply more likely and the rejected reply less likely, using pairs of answers you ranked."),
    "preference": ("Preference pair", "One judgement: for this prompt, reply A was better than reply B. These pairs are the training material for feedback training."),
    "beta": ("β (beta)", "A caution dial. High β keeps the model close to where it started (small safe changes); low β lets it change a lot, faster but riskier."),
    "sft": ("SFT mix-in", "Supervised fine-tuning: ordinary learning that copies the preferred replies. A little of it alongside feedback training keeps small models coherent."),
    "perplexity": ("Perplexity", "How many equally likely choices the model feels it has for each next character. Lower is better; 2 means it is quite sure, 50 means it is nearly guessing."),
    "token_error": ("Wrong-word rate (token error)", "How often the model's top guess for the next character is wrong when reading correct answers. A new model is wrong 90%+ of the time; under about 45% it is usually worth polishing."),
    "win_rate": ("Win rate", "The share of head-to-head comparisons the new model won against the old one. 50% means no real difference; 55%+ is a real edge."),
    "judge": ("Judge model", "The model that grades two answers and picks the better one. It can be the same as the teacher."),
    "rubric": ("Rubric", "The list of rules the teacher grades answers by. Bigger weights matter more."),
    "reward_accuracy": ("Reward accuracy", "How often the model now ranks the preferred reply above the rejected one. Watch it on held-out pairs."),
    "loss_type": ("Loss type", "The maths used for feedback training. 'dpo' is the standard; 'ipo' is steadier when your judgements are noisy."),
    "arena": ("Compare checkpoints", "A fair contest: two models answer the same prompts and a judge picks the winner each time."),
    # ---- extra terms
    "working_dataset": ("Working dataset", "The dataset the other pages act on: training, feedback prompts and saved corrections all use it. Pick it on the Your data page."),
    "sample_size": ("Source sample size", "How many of your existing examples are shown to the generator as raw material. More variety, but slower."),
    "attempts": ("Attempt multiplier", "The generator tries this many times more candidates than you asked for, because some are thrown away by the quality checks."),
    "teacher_batch": ("Examples per teacher call", "How many examples the teacher model writes in each request. Smaller batches are slower but easier for small teachers."),
    "repetition": ("Repetition limit", "Rejects answers where too much of the text is the same words repeated over and over (0.65 = at most 65% repeated)."),
    "near_duplicate": ("Near-duplicate cutoff", "Also rejects examples that are almost, but not exactly, the same as another. 0 turns this off; 0.9 rejects very similar ones."),
    "candidates": ("Answers per prompt", "How many different replies your model writes for each prompt so the teacher can compare them."),
    "rounds": ("Rounds", "One round = write answers, grade them, train, then test. More rounds keep improving the model if each one wins."),
    "must_win": ("Must win at least (%)", "The share of head-to-head tests the new model has to win before it replaces the old one. 55% is a small but real edge."),
    "learning_speed": ("Learning speed", "Like the learning rate in ordinary training: how big each adjustment is. Smaller is safer."),
    "pairs_per_step": ("Pairs per step", "How many preference pairs the model studies before each adjustment."),
    "creativity_ab": ("Reply creativity", "Two replies are written with different temperatures (adventurousness) so you have something to compare."),
    "prompt_count": ("Prompts per round", "How many different prompts are used in each round of automated improvement."),
}

# every module the registry offers (studio_registry.for_slot), by slot, -> its GLOSSARY entry
MODULE_TERMS = {
    "embedding": {"learned": "embedding", "factorized": "factorized_embedding"},
    "position": {"learned": "learned_position", "sinusoidal": "sinusoidal", "rope": "rope", "alibi": "alibi", "none": "nope"},
    "norm": {"layernorm": "layernorm", "rmsnorm": "rmsnorm", "none": "no_norm"},
    "mixer": {"attention": "attention", "gqa": "gqa", "linear": "linear_attention", "ssm": "ssm", "gru": "gru", "lstm": "lstm",
              "conv": "conv", "none": "no_mixer"},
    "channel": {"mlp_gelu": "mlp_gelu", "swiglu": "swiglu", "moe": "moe", "none": "no_channel"},
    "head": {"tied": "tied_head", "untied": "untied_head"},
}


def glossary_text(key):
    term, text = GLOSSARY[key]
    return f"{term}\n{text}"
